    select(id, proba_inter, proba_build, proba_rfl) |&gt;
    separate(id, into = c('nidt', 'grid_id'), sep = ":") |&gt;
    group_by(nidt) |&gt;
    mutate(
        proba_build = proba_build/sum(proba_build),
        proba_rfl = proba_rfl/sum(proba_rfl),
        ) |&gt;
    unite(col = "id", nidt, grid_id, sep = ":")

